            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Trends the worst site’s inter\\-device link availability as a percentage, read from Catalyst Center’s InterDeviceLinkAvailHealth field on raw cisco:dnac:devicehealth events\\."
            }
        },
        "viz_card_02_singlevalue": {
            "type": "splunk.singlevalue",
